# XOR two byte strings (handles different lengths)
def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

# Check if text might be an English word or sentence
def is_likely_english(text, min_printable_ratio=0.7):
    printable_chars = sum(c in string.printable for c in text)
    return printable_chars / len(text) >= min_printable_ratio

# Try to recover plaintext by inferring spaces and letters
def recover_plaintext_with_spaces(ct1, ct2):
    xored = xor_bytes(ct1, ct2)

    # Analyze for likely space patterns
    # When a space (0x20) in one plaintext XORs with a letter in another,
    # the result is a letter with the same case (XOR with space flips case)

    potential_spaces = []
    for i in range(len(xored)):
        byte = xored[i]
        # Check if the XORed byte could be a letter XOR a space
        if (65 <= byte <= 90) or (97 <= byte <= 122):
            potential_spaces.append(i)

    # Guess spaces and see if we get readable text
    for i in potential_spaces:
        # Assume a space in ct1 at this position
        if i < len(ct1):
            key_byte = ct1[i] ^ ord(' ')
            if i < len(ct2):
                pt2_char = chr(ct2[i] ^ key_byte)
                if pt2_char.isalnum() or pt2_char in string.punctuation or pt2_char.isspace():
                    # This is a potential match - try to recover more around this position
                    key_fragment = bytearray([0] * len(ct1))
                    key_fragment[i] = key_byte

                    # Extend the key in both directions by inferring more bytes
                    extend_key(key_fragment, ct1, i, 20)

                    # Decrypt using the key fragment
                    pt1 = decrypt_with_key_fragment(ct1, key_fragment)
                    if pt1 and is_likely_english(pt1, 0.8):
                        print(f"Potential plaintext 1: {pt1}")

                    pt2 = decrypt_with_key_fragment(ct2, key_fragment)
                    if pt2 and is_likely_english(pt2, 0.8):
                        print(f"Potential plaintext 2: {pt2}")

# Extend a key fragment from a known byte
def extend_key(key_fragment, ciphertext, start_pos, lookahead):
    common_chars = " etaoinshrdlucmfwypvbgkjqxz-,.?!:;()[]{}\"'ETAOINSHRDLUCMFWYPVBGKJQXZ"

    # Assuming a key byte at start_pos, try to infer more key bytes
    for offset in range(1, lookahead):
        if start_pos + offset >= len(ciphertext):
            break

        # Try different common characters and see which produces valid characters when XORed
        best_score = 0
        best_key_byte = 0

        for char in common_chars:
            key_byte = ciphertext[start_pos + offset] ^ ord(char)
            score = 0

            # Test this key byte on the ciphertext
            for i in range(len(ciphertext)):
                if i == start_pos + offset:
                    continue  # Skip the position we're inferring
                if i < len(ciphertext):
                    test_char = chr(ciphertext[i] ^ key_byte)
                    if test_char.isalnum() or test_char in string.punctuation or test_char.isspace():
                        score += 1

            if score > best_score:
                best_score = score
                best_key_byte = key_byte

        if best_score > 0:
            key_fragment[start_pos + offset] = best_key_byte

    # Do the same for positions before start_pos
    for offset in range(1, lookahead):
        if start_pos - offset < 0:
            break

        best_score = 0
        best_key_byte = 0

        for char in common_chars:
            key_byte = ciphertext[start_pos - offset] ^ ord(char)
            score = 0

            for i in range(len(ciphertext)):
                if i == start_pos - offset:
                    continue
                if i < len(ciphertext):
                    test_char = chr(ciphertext[i] ^ key_byte)
                    if test_char.isalnum() or test_char in string.punctuation or test_char.isspace():
                        score += 1

            if score > best_score:
                best_score = score
                best_key_byte = key_byte

        if best_score > 0:
            key_fragment[start_pos - offset] = best_key_byte

# Decrypt with a key fragment
def decrypt_with_key_fragment(ciphertext, key_fragment):
    result = ""
    for i in range(len(ciphertext)):
        if i < len(key_fragment) and key_fragment[i] != 0:
            decrypted_byte = ciphertext[i] ^ key_fragment[i]
            if 32 <= decrypted_byte <= 126:  # Printable ASCII
                result += chr(decrypted_byte)
            else:
                result += "?"  # Non-printable character
        else:
            result += "?"  # Unknown key byte

    return result

# Perform crib-dragging to find possible plaintext
def crib_drag(ciphertexts):
    promising_fragments = []

    # List of likely words or patterns to look for
    cribs = [
        "flag", "secret", "password", "key", "document", "classified", 
        "mission", "agent", "target", "operation", "intel", "directive",
