                            # We may have found a match
                            # The crib might be in pt2 and pt1_text is in pt1
                            key_fragment = xor_bytes(ct1[pos:pos+len(crib_bytes)], pt1_fragment)

                            # Use the key fragment to decrypt more of both messages
                            extended_pt1 = ""
                            extended_pt2 = ""

                            for k in range(max(0, pos-20), min(len(ct1), pos+len(crib_bytes)+20)):
                                if k-pos < len(key_fragment) and k-pos >= 0:
                                    key_byte = key_fragment[k-pos]
