#!/usr/bin/env python3

import base64
import re
import string
from itertools import combinations

def extract_ciphertexts(filename):
    with open(filename, 'r') as file:
        content = file.read()

    # Extract base64 encoded blocks
    pattern = r'[A-Za-z0-9+/=]{20,}'
    ciphertexts_b64 = re.findall(pattern, content)

    # Decode base64 to bytes
    ciphertexts = [base64.b64decode(ct) for ct in ciphertexts_b64]

    return ciphertexts

def xor_bytes(a, b):
    """XOR two byte strings"""
    return bytes(x ^ y for x, y in zip(a, b))

def score_text(text):
    """Score a piece of text for likelihood of being English"""
    printable_chars = 0
    letter_count = 0
    space_count = 0

    for char in text:
        if 32 <= char <= 126:  # Printable ASCII
            printable_chars += 1
            if 65 <= char <= 90 or 97 <= char <= 122:  # Letters
                letter_count += 1
            if char == 32:  # Space
                space_count += 1

    if len(text) == 0:
        return 0

    # Good text should be mostly printable and have a decent number of spaces
    return (printable_chars / len(text)) * (letter_count / max(1, len(text))) * (1 + space_count / max(1, len(text)))

def is_printable(text):
    """Check if a byte string is likely to be readable text"""
    return all(32 <= b <= 126 for b in text)

def crib_drag(ct1, ct2, crib):
    """Try a known plaintext against all positions in XORed ciphertexts"""
    results = []
    xored = xor_bytes(ct1, ct2)
    crib_bytes = crib.encode()

    for i in range(len(xored) - len(crib_bytes) + 1):
        segment = xored[i:i+len(crib_bytes)]

        # XOR the segment with the crib to get a potential plaintext fragment
        potential_plaintext = xor_bytes(segment, crib_bytes)

        # Check if the potential plaintext looks like valid text
        if is_printable(potential_plaintext):
            # Get extended context by using the knowledge we have
            start = max(0, i - 10)
            end = min(len(xored), i + len(crib_bytes) + 10)

            # Recover key fragment using the crib
            key_fragment = xor_bytes(ct1[i:i+len(crib_bytes)], crib_bytes)

            # Use key fragment to decrypt larger portions
            pt1_extended = ""
            pt2_extended = ""

            for j in range(start, end):
                if j >= i and j < i + len(crib_bytes):
                    idx = j - i
                    if idx < len(key_fragment):
                        if j < len(ct1):
                            pt1_extended += chr(ct1[j] ^ key_fragment[idx])
                        else:
                            pt1_extended += "?"
                        if j < len(ct2):
                            pt2_extended += chr(ct2[j] ^ key_fragment[idx])
                        else:
                            pt2_extended += "?"
                    else:
                        pt1_extended += "?"
                        pt2_extended += "?"
                else:
                    pt1_extended += "?"
                    pt2_extended += "?"

            results.append((i, potential_plaintext, pt1_extended, pt2_extended))

    return results

def find_spaces(ct1, ct2):
    """Find potential space characters by analyzing XORed ciphertexts"""
    xored = xor_bytes(ct1, ct2)
    space_positions = []

    for i, byte in enumerate(xored):
        # When XORing a space with a letter, the result typically has the 5th bit set
        # (uppercase and lowercase ASCII letters differ by this bit)
        if (byte >= 65 and byte <= 90) or (byte >= 97 and byte <= 122):
            space_positions.append(i)

    return space_positions

def recover_keystream(ciphertexts, max_len):
    """Try to recover keystream by analyzing multiple ciphertexts"""
    keystream = bytearray([0] * max_len)
    keystream_known = [False] * max_len

    # Score all possible values for each byte in the keystream
    for pos in range(max_len):
        candidates = {}

        for ct in ciphertexts:
            if pos < len(ct):
                for char in range(32, 127):  # Printable ASCII
                    key_byte = ct[pos] ^ char
                    if key_byte not in candidates:
                        candidates[key_byte] = 0
                    candidates[key_byte] += 1

        # Choose the most likely key byte
        if candidates:
            sorted_candidates = sorted(candidates.items(), key=lambda x: x[1], reverse=True)
            keystream[pos] = sorted_candidates[0][0]
            keystream_known[pos] = True

    return bytes(keystream), keystream_known

