        except:
            print(f"CT{i+1}: {decrypted[:100]}")

    # Try crib dragging with common words and phrases
    cribs = [
        "flag", "FLAG", "key", "secret", "FLAG{", "CTF", "password",
        "the ", "and ", "this", "that", "TARGET:", "LOCATION:", "AGENT:",
        "MISSION:", "SECRET:", "CONFIDENTIAL"
    ]

    # Display header for crib-dragging results
    print("\n=== Crib-dragging Results ===")

    # Apply crib dragging to each pair of ciphertexts
    promising_results = []

    # Only process a subset of ciphertext pairs to keep output manageable
    for (i, ct1), (j, ct2) in combinations(enumerate(ciphertexts[:20]), 2):
