#!/usr/bin/env python3

import base64
import re
import itertools
from pwn import *

def extract_ciphertexts(filename):
    with open(filename, 'r') as file:
        content = file.read()

    # Extract base64 encoded blocks
    pattern = r'[A-Za-z0-9+/=]{20,}'
    ciphertexts_b64 = re.findall(pattern, content)

    # Decode base64 to bytes
    ciphertexts = [base64.b64decode(ct) for ct in ciphertexts_b64]

    return ciphertexts

def xor_bytes(a, b):
    """XOR two byte strings"""
    return bytes(x ^ y for x, y in zip(a, b))

def is_printable(byte_val):
    """Check if a byte value corresponds to a printable ASCII character"""
    return 32 <= byte_val <= 126

def recover_keystream_at_position(ct1, ct2, known_text, position):
    """Recover keystream using known plaintext at a position"""
    if position + len(known_text) > min(len(ct1), len(ct2)):
        return None

    # Extract the segment of ciphertext at the position
    segment = ct1[position:position+len(known_text)]

    # XOR known plaintext with ciphertext segment to get the keystream
    keystream = xor_bytes(segment, known_text.encode())

    return keystream

def decrypt_with_keystream(ciphertext, keystream, position):
    """Decrypt a portion of ciphertext using a known keystream starting at position"""
    if position + len(keystream) > len(ciphertext):
        return None

    # Extract the segment to decrypt
    segment = ciphertext[position:position+len(keystream)]

    # XOR segment with keystream to get plaintext
    plaintext = xor_bytes(segment, keystream)

    # Convert to string if it's printable
    try:
        return plaintext.decode('ascii')
    except:
        return ''.join(chr(b) if 32 <= b <= 126 else '�' for b in plaintext)

